<?php
require 'includes/bootstrap.php'; require_admin(); require 'includes/layout.php';
$view=$_GET['view']??'drivers';if(!in_array($view,['drivers','guides','packages','content'],true))$view='drivers';
$map=['drivers'=>['driver_services','service_json'],'guides'=>['guide_services','service_json'],'packages'=>['travel_packages','package_json']];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 if($view==='content'){$slug=(string)($_POST['slug']??'');$version=trim((string)($_POST['version']??''));$title=json_decode((string)($_POST['title_json']??''),true);$body=json_decode((string)($_POST['body_json']??''),true);if($slug&&$version&&is_array($title)&&is_array($body)){db()->prepare('UPDATE content_documents SET version=?,title_json=?,body_json=? WHERE slug=?')->execute([$version,json_encode($title,JSON_UNESCAPED_UNICODE),json_encode($body,JSON_UNESCAPED_UNICODE),$slug]);flash('success','Content updated.');}else flash('error','Title and body must be valid JSON.');}
 else{[$table]=$map[$view];$action=$_POST['action']??'status';$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'');$allowed=$view==='packages'?['draft','published','paused','archived']:['draft','review','published','paused','rejected'];if($action==='create'){$payload=json_decode((string)($_POST['payload']??''),true);if(!is_array($payload))flash('error','Payload must be valid JSON.');else{$id=new_uuid();if($view==='packages')db()->prepare("INSERT INTO travel_packages(id,status,package_json) VALUES(?,'draft',?)")->execute([$id,json_encode(['id'=>$id,...$payload],JSON_UNESCAPED_UNICODE)]);elseif($view==='drivers')db()->prepare("INSERT INTO driver_services(id,status,city,category,title_json,service_json) VALUES(?,'draft',?,?,?,?)")->execute([$id,trim($_POST['city']??''),trim($_POST['category']??''),json_encode($payload['title']??[],JSON_UNESCAPED_UNICODE),json_encode(['id'=>$id,...$payload],JSON_UNESCAPED_UNICODE)]);else db()->prepare("INSERT INTO guide_services(id,status,city,title_json,service_json) VALUES(?,'draft',?,?,?)")->execute([$id,trim($_POST['city']??''),json_encode($payload['title']??[],JSON_UNESCAPED_UNICODE),json_encode(['id'=>$id,...$payload],JSON_UNESCAPED_UNICODE)]);flash('success','Draft catalog record created.');}}elseif($id&&in_array($status,$allowed,true)){db()->prepare("UPDATE $table SET status=? WHERE id=?")->execute([$status,$id]);flash('success','Publication status updated.');}}
 redirect('catalog.php?view='.$view);
}
if($view==='content')$rows=db()->query('SELECT * FROM content_documents ORDER BY slug')->fetchAll();else{[$table,$field]=$map[$view];$rows=db()->query("SELECT id,status,$field payload,updated_at FROM $table ORDER BY updated_at DESC")->fetchAll();}
page_header('Mobile catalog'); ?>
<?php if($view!=='content'):?><section class="panel reservation-form"><div class="panel-head"><div><p class="eyebrow">NEW DRAFT</p><h3>Create catalog record</h3></div></div><form method="post" class="editor-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create"><?php if($view!=='packages'):?><label>City<input name="city" required></label><?php endif;?><?php if($view==='drivers'):?><label>Category<input name="category" required></label><?php endif;?><label>Complete JSON payload<textarea name="payload" rows="8" required>{"title":{"es":"","en":"","ar":""},"priceMinor":0,"currency":"EUR"}</textarea></label><button class="btn primary wide">Create draft</button></form></section><?php endif;?>
<div class="filters people-tabs"><?php foreach(['drivers'=>'Driver services','guides'=>'Guide services','packages'=>'Travel packages','content'=>'Legal & app content'] as $key=>$label):?><a class="<?=$view===$key?'active':''?>" href="?view=<?=$key?>"><?=e($label)?></a><?php endforeach;?></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">MOBILE DATA</p><h3><?=count($rows)?> records</h3></div></div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Preview</th><th>Status / content</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($view==='content'?$row['slug']:substr($row['id'],0,18))?></strong></td><td><small><?=e(mb_strimwidth($view==='content'?$row['title_json']:$row['payload'],0,120,'…'))?></small></td><td><?php if($view==='content'):?><form method="post" class="status-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="slug" value="<?=e($row['slug'])?>"><input name="version" value="<?=e($row['version'])?>"><textarea name="title_json" rows="2"><?=e($row['title_json'])?></textarea><textarea name="body_json" rows="3"><?=e($row['body_json'])?></textarea><button class="btn secondary">Save</button></form><?php else:?><form method="post" class="status-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><select name="status" onchange="this.form.submit()"><?php $states=$view==='packages'?['draft','published','paused','archived']:['draft','review','published','paused','rejected'];foreach($states as $s):?><option value="<?=$s?>" <?=$row['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></form><?php endif;?></td><td><?=e($row['updated_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">No records yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php page_footer();
